const readline = require('readline')
const { EventEmitter } = require('events')

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
})

const addSpaceBeforeQuestion = (question) => `${question} `

module.exports = (questions, done) => {
    const answers = []
    const firstQuestion = questions[0]
    const emitter = new EventEmitter()
    const questionAnswered = answer => {
        emitter.emit("answer", answer)
        answers.push(answer.trim())
        if (answers.length < questions.length) {
            rl.question(addSpaceBeforeQuestion(questions[answers.length]), questionAnswered)

        }
        else return done(answers)
    }
    rl.question(addSpaceBeforeQuestion(firstQuestion), questionAnswered)
    return emitter
}